/* Culture apparatus as true orbitable geometry, with separate air/liquid paths. */
(()=>{'use strict';const M=CultureModels,TAU=Math.PI*2,blue='#73b2be',air='#c59a5a';
function pipe(w,pts,color='#aab8a7',width=4){w.line(pts,color,width);w.line(pts,'#e4eadd',.6,{alpha:.7})}
function ring(w,x,y,z,r,color='#d0d5c2',width=2){const a=Array.from({length:49},(_,i)=>[x+Math.cos(i/48*TAU)*r,y,z+Math.sin(i/48*TAU)*r]);w.line(a,color,width)}
function bench(w,level=-.3){w.box(0,level,.1,13,.25,7,'#dce0ce');for(const x of [-5,5])for(const z of [-2.5,2.5])w.box(x,level-1.1,z,.15,1.1,.15,'#b9c4b0');w.line([[-6.2,level+.3,2.9],[6.2,level+.3,2.9]],'#f1ede0',2)}
function container(w,x,y,z,type,{r=1.25,height=1.8,treatment=2}={}){const top=y+height,col=type==='soil'?'#b39a72':type==='sand'?'#d8c99d':'#98bdba';w.cylinder(x,y,z,r,.09,'#aab49c',{n:28});
for(let i=0;i<30;i++){const a=i/30*TAU,b=(i+1)/30*TAU;if(Math.sin((a+b)/2)<-.18)continue;w.poly([[x+Math.cos(a)*r,y,z+Math.sin(a)*r],[x+Math.cos(b)*r,y,z+Math.sin(b)*r],[x+Math.cos(b)*r,top,z+Math.sin(b)*r],[x+Math.cos(a)*r,top,z+Math.sin(a)*r]],'#bcc8b0',{line:'#dce3d3'});if(type!=='hydro'){const rr=r*.93;w.poly([[x+Math.cos(a)*rr,y+.12,z+Math.sin(a)*rr],[x+Math.cos(b)*rr,y+.12,z+Math.sin(b)*rr],[x+Math.cos(b)*rr,top-.08,z+Math.sin(b)*rr],[x+Math.cos(a)*rr,top-.08,z+Math.sin(a)*rr]],col)}}
ring(w,x,top,z,r,'#e2e7d8',3);w.cylinder(x,y+.1,z,r*.94,height-.18,col,{n:30,alpha:type==='hydro'?.27:.19});
if(type!=='hydro'){for(let i=0;i<65;i++){const a=i*2.399,rr=.9*Math.sqrt((i%17)/17),yy=y+.2+(i*.137)%(height-.3),zz=z+.3+Math.abs(Math.sin(a))*.6;w.dot([x+Math.cos(a)*rr,yy,zz],type==='sand'?.029:.045,type==='sand'?['#e5d8af','#bcae83','#f0e5c3'][i%3]:['#987b53','#b49a70','#87734f'][i%3],{alpha:.8})}}
else{w.box(x,top+.02,z,2*r,.07,2*r,'#8da58d');w.cylinder(x,top+.08,z,.18,.08,'#d7dec9',{n:16});}
w.label([x,y+.13,z-r],M.treatments[treatment],{size:12,pill:true,color:M.colors[treatment],dy:18});return top}
function plant(w,x,top,z,type,t,{scale=.78,response=false,day=28}={}){const g=response?(.42+.58*(day/28))*(.67+.165*t):.72;MaizeUptake.drawPlant(w,{x,y:top+.09,z,scale,shootScale:g,rootScale:.59});const count=type==='soil'?2+t*3:t*4;if(count)w.stream([[x+.78,top-1.12,z-.38],[x+.43,top-.6,z-.18],[x,top+.05,z],[x,top+.63*scale,z]],'#65acb8',{count,size:.023,speed:.075,trail:false});}
function bubbles(w,x,y,z,height=1.4){for(let i=0;i<15;i++){const f=(w.time*.24+i/15)%1;w.dot([x+.14*Math.sin(i*2+f*4),y+f*height,z+.1*Math.cos(i)],.027+(i%3)*.01,'#d4ece6',{alpha:.75})}}
function layout(w,s,type){bench(w);for(const row of s.layout)for(const u of row){const x=(u.column-1)*3.4,z=(u.block-1.5)*1.65;w.cylinder(x,.04,z,.44,.54,type==='hydro'?'#8eaaa0':type==='sand'?'#d7cba8':'#b5a17d',{n:12});MaizeUptake.drawPlant(w,{x,y:.6,z,scale:.2,shootScale:.8,roots:false});w.label([x,.14,z-.47],`${M.treatments[u.treatment]} · B${u.block+1}`,{pill:true,size:9,color:M.colors[u.treatment]});if(type!=='soil')w.box(x+.66,.02,z,.38,.28,.4,'#a0bbb1');}w.label([0,2.2,0],'4 个区组 · 每区组 3 个磷处理',{size:16,color:'#5c7e58'});w.label([0,-.55,3.5],type==='soil'?'每盆独立，盆内取样不增加重复数':'每个容器 / 盆配独立液路；共用气源不共用营养液',{size:11,pill:true,color:'#839177'})}
function comparison(w,s,type){bench(w);for(let t=0;t<3;t++){const x=(t-1)*3.8,top=container(w,x,.1,0,type,{r:1.1,height:1.65,treatment:t});plant(w,x,top,0,type,t,{scale:.7,response:true,day:s.day});w.label([x,4.7,0],type==='soil'?`${M.soilP[t]} mg P/kg`:`${M.solutionP[t].toFixed(2)} mmol P/L`,{size:12,color:M.colors[t]});if(type==='hydro'&&s.aeration)bubbles(w,x+.47,.2,-.25,1.35)}w.label([0,-.6,1.8],'生长差异为示意 · 数据另列，不由株高推算产量',{size:11,pill:true,color:'#88977b'})}
function soil(w,s){if(s.step===4)return layout(w,s,'soil');if(s.step>=6)return comparison(w,s,'soil');bench(w);const top=container(w,1.6,.1,0,'soil',{treatment:s.treatment});plant(w,1.6,top,0,'soil',s.treatment,{scale:.9});
if(s.step===1){w.box(-3.4,.2,0,3,.15,2.2,'#b7c3ab');w.box(-3.4,.37,0,2.6,.18,1.7,'#ac9169');for(let i=0;i<8;i++){const x=-4.5+i*.32;w.line([[x,.59,-.8],[x,.59,.8]],'#d4d7c2',1)}for(let i=0;i<6;i++){const z=-.75+i*.3;w.line([[-4.6,.59,z],[-2.2,.59,z]],'#d4d7c2',1)}w.label([-3.4,1.25,0],'3 mm 过筛 · 全量混匀',{size:13,pill:true});w.label([1.6,-.3,0],'同一批土 · 干土当量 5 kg',{size:12,pill:true})}
else if(s.step===2){const d=M.dose('soil',s.treatment,5);w.cylinder(-3.1,.1,0,.66,1.05,'#a9b9a3',{n:20});w.label([-3.1,1.6,0],`${M.treatments[s.treatment]}：${d.pMg.toFixed(0)} mg P / 盆`,{size:13,pill:true,color:M.colors[s.treatment]});w.stream([[-3.1,1.35,0],[-.5,2.7,0],[1.6,1.9,0]],'#6da8ae',{count:s.treatment?12:0,size:.04,speed:.15});w.label([-2,.2,1.5],'KH₂PO₄ 带入 K → 扣减 KCl 补量',{size:11,pill:true});}
else if(s.step===3){w.label([1.6,4.4,0],'同龄幼苗 · 每盆 1 株',{size:15,pill:true});w.label([-2,1.5,0],'混肥 → 装盆 → 播种 → 定苗',{size:12,pill:true});}
else if(s.step===5){w.box(1.6,-.12,0,3.1,.2,2.8,'#98aaa0');w.box(1.6,-.02,-1.65,1.5,.5,.12,'#b4c2ad');w.label([1.6,.2,-1.76],`${s.waterAdded?'7.10':'6.85'} kg`,{size:16,pill:true,color:'#54807b'});if(s.waterAdded)w.stream([[0,3.15,0],[.5,2.7,0],[1.5,1.95,0]],blue,{count:10,speed:.2,size:.045});w.label([-2,1.8,0],s.waterAdded?'补水 250 g → 回到目标盆重':'称重 6.85 kg → 距目标差 250 g',{size:12,pill:true});w.label([-2,.8,0],'示例目标 7.10 kg（含附属物校正）',{size:10,color:'#8a967d'});}
else{w.label([-2.8,2.4,0],'土壤供磷 + 新增磷肥',{size:16,pill:true,color:'#8b7956'});w.stream([[-2.8,1.6,0],[-.2,1.2,0],[1.6,.9,0]],'#7fb3ae',{count:8,size:.045,speed:.12});w.label([1.6,4.4,0],'玉米 · 苗期磷响应',{size:14,pill:true})}}
function sand(w,s){if(s.step===6)return layout(w,s,'sand');if(s.step>=7)return comparison(w,s,'sand');bench(w,-2);w.box(-4.55,-1.75,0,2.35,1.1,2.35,'#c8d0bd');w.box(2,.77,0,2.9,.12,2.9,'#bac5ae');for(const x of [.75,3.25])for(const z of [-1.2,1.2])w.box(x,-1.75,z,.12,2.52,.12,'#b1bea5');const px=2,top=container(w,px,.9,0,'sand',{treatment:s.treatment});plant(w,px,top,0,'sand',s.treatment,{scale:.88});const e=M.irrigation(s.phase,s.fraction),ry=-.65,rx=-4.55,bx=-1.7,by=-1.7;
// Reservoir is above the bottle's refill level, below the pot drain.
w.cylinder(rx,ry,0,1.05,1.25,'#a8c3b6',{n:24,alpha:.22});w.cylinder(rx,ry+.06,0,.98,.12+e.reservoir*.075,blue,{n:24,alpha:.65});ring(w,rx,ry+1.25,0,1.05);w.label([rx,ry-.18,0],'贮液槽 · 本盆独立',{size:12,pill:true});
w.cylinder(bx,by,0,.47,2.4,'#c4d9ce',{n:22,alpha:.23});w.cylinder(bx,by+.05,0,.42,.08+e.bottle*.53,blue,{n:20,alpha:.64});w.cylinder(bx,by+2.4,0,.49,.1,'#95a68e',{n:20});w.label([bx,by-.2,0],'定量输液瓶',{size:11,pill:true});
const refill=[[rx,-.35,0],[-3.2,-.35,0],[-3.2,-1.3,0],[bx,-1.3,0]],outlet=[[bx,-1.5,0],[bx+.5,-1.5,0],[bx+.5,3.25,0],[px,3.25,0],[px,3.04,0]],drain=[[px,.92,0],[px,.65,0],[rx,.65,0],[rx,.35,0]];
pipe(w,refill);pipe(w,outlet);pipe(w,drain);w.dot([-3.2,-1.3,0],.15,e.checkOpen?'#88ac7e':'#cc9c5d');w.label([-3.2,-1.3,0],e.checkOpen?'止回阀：开':'止回阀：关',{dy:23,size:10,pill:true});
// The air hose terminates in the headspace; it never carries nutrient liquid.
w.box(-5,.18,2,1,.55,.75,'#a7b49a');const gas=[[-5,.65,2],[-5,3.65,1.2],[bx,3.65,1.2],[bx,.72,0]];w.line(gas,air,2,{dash:[5,5]});w.label([-4.6,3.8,1.2],e.pressure?'气阀：开 · 加压':'气阀：卸压 / 待机',{size:11,pill:true,color:'#aa8550'});if(e.pressure)w.stream(gas,air,{count:8,size:.035,speed:.2});
ring(w,px,3.02,0,.82,blue,3);if(e.spray){w.stream(outlet,blue,{count:15,size:.045,speed:.2});for(let i=0;i<8;i++){const a=i/8*TAU;w.stream([[px+Math.cos(a)*.82,3.02,Math.sin(a)*.82],[px+Math.cos(a)*.9,top+.02,Math.sin(a)*.9],[px+Math.cos(a)*.7,1.35,Math.sin(a)*.7]],blue,{count:3,size:.032,speed:.27,phase:i*.13})}}
if(e.drain)w.stream(drain,blue,{count:12,size:.045,speed:.2});if(e.refill)w.stream(refill,blue,{count:9,size:.04,speed:.18});w.label([px,top+.35,-1.25],'砂面给液 ↓',{size:12,pill:true,color:'#5c8d91'});w.label([.1,4.85,0],`${s.phase+1} / 4 · ${M.phaseNames[s.phase]}`,{size:17,pill:true,color:'#577c61'});
if(s.step===1)w.label([px,.45,1.2],'石英砂 · 粗砂排水层 · 挡砂结构',{size:11,pill:true});if(s.step===2)w.label([rx,1.3,0],`${M.solutionP[s.treatment].toFixed(2)} mmol P/L · K 配平`,{size:11,pill:true});}
function hydro(w,s){if(s.step===4)return layout(w,s,'hydro');if(s.step>=6)return comparison(w,s,'hydro');bench(w);const px=1.7,top=container(w,px,.1,0,'hydro',{treatment:s.treatment});plant(w,px,top,0,'hydro',s.treatment,{scale:.92});const pump=[[-3.8,.65,0],[-3.8,2.5,0],[.7,2.5,0],[.7,.3,0],[px,.3,0]];w.box(-3.8,.1,0,1.2,.55,.85,'#9eae97');pipe(w,pump,air,2);w.box(px,.23,0,.5,.1,.25,'#a1b6ad');if(s.aeration){bubbles(w,px,.35,-.2,1.25);w.stream(pump,air,{count:10,speed:.2,size:.035})}w.label([-3.8,1.2,0],s.aeration?'气泵：开启':'气泵：关闭（干扰条件）',{size:12,pill:true,color:'#9d8459'});w.label([px,4.6,0],'玉米 · 遮光容器的剖视示意',{size:14,pill:true});w.label([px,2.12,-1.1],'根颈在液面以上',{size:11,pill:true});
if([1,2].includes(s.step)){for(let i=0;i<3;i++){const x=-4.7+i*1.25;w.cylinder(x,.1,1.8,.35,.95,i===2?'#9eb7b5':'#c5c9ad',{n:16,alpha:.8});w.label([x,1.3,1.8],['共同背景','磷盐','补钾'][i],{size:10,pill:true})}w.label([-2,3.6,0],s.step===1?'分开加液 · 混匀 · 定容':'总 K = 3.00 mmol/L',{size:14,pill:true,color:'#6d9390'});}
else if(s.step===3)w.label([-2,3.5,0],'同龄苗 → 过渡 → 固定 → 处理计时',{size:12,pill:true});else if(s.step===5){w.label([-2.5,3.5,0],s.renewed?'更换本处理新鲜营养液':'补水、pH、EC 与磷浓度分别记录',{size:12,pill:true});if(s.renewed)w.stream([[-2,3.2,-.7],[0,2.3,-.7],[1.7,1.6,-.7]],blue,{count:12,speed:.18,size:.045})}else w.label([-2,3.5,0],`${M.solutionP[s.treatment].toFixed(2)} mmol P/L · 改良半量霍格兰`,{size:13,pill:true});}
window.CultureWorlds={draw(w,s){if(s.type==='soil')soil(w,s);else if(s.type==='sand')sand(w,s);else hydro(w,s)}};
})();


